<?php
namespace App\Http\Controllers\Operations;use App\Http\Controllers\Controller;use App\Models\{LaundryOrder,LaundryOrderItem,LaundryService,Stay,User};use App\Services\Operations\LaundryServiceManager;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Illuminate\Support\Str;
class LaundryController extends Controller{public function index(){ $p=auth()->user()->property_id;return view('operations.laundry.index',['orders'=>LaundryOrder::with(['room','guest','items.service'])->where('property_id',$p)->latest()->paginate(50),'services'=>LaundryService::where('property_id',$p)->where('is_active',1)->orderBy('name')->get(),'stays'=>Stay::with(['room','guest','folio'])->where('property_id',$p)->where('status','in_house')->get(),'staff'=>User::where('property_id',$p)->where('is_active',1)->orderBy('name')->get()]);}public function service(Request $r){$d=$r->validate(['name'=>'required|string|max:255','unit'=>'required|string|max:30','guest_price'=>'required|numeric|min:0','internal_cost'=>'nullable|numeric|min:0','turnaround_hours'=>'required|integer|min:1']);LaundryService::create($d+['property_id'=>auth()->user()->property_id,'is_active'=>true]);return back()->with('success','Laundry service added.');}public function store(Request $r){$p=auth()->user()->property_id;$d=$r->validate(['stay_id'=>'nullable|integer','type'=>'required|in:guest,hotel','laundry_service_id'=>'required|array|min:1','laundry_service_id.*'=>'integer','quantity'=>'required|array','quantity.*'=>'numeric|min:0.01','notes'=>'nullable|string','assigned_to'=>'nullable|integer']);$stay=!empty($d['stay_id'])?Stay::with('folio')->where('property_id',$p)->findOrFail($d['stay_id']):null;if($d['type']==='guest'&&!$stay)abort(422,'Select an in-house stay for guest laundry.');DB::transaction(function()use($d,$p,$stay){$order=LaundryOrder::create(['property_id'=>$p,'stay_id'=>$stay?->id,'room_id'=>$stay?->room_id,'guest_id'=>$stay?->guest_id,'folio_id'=>$stay?->folio?->id,'reference'=>'LAU-'.now()->format('YmdHis').'-'.strtoupper(Str::random(4)),'type'=>$d['type'],'status'=>'received','received_at'=>now(),'received_by'=>auth()->id(),'assigned_to'=>$d['assigned_to']??null,'notes'=>$d['notes']??null]);$total=0;foreach($d['laundry_service_id'] as $i=>$sid){$service=LaundryService::where('property_id',$p)->findOrFail($sid);$qty=(float)($d['quantity'][$i]??0);if($qty<=0)continue;$price=$d['type']==='guest'?(float)$service->guest_price:(float)$service->internal_cost;$line=$qty*$price;LaundryOrderItem::create(['laundry_order_id'=>$order->id,'laundry_service_id'=>$service->id,'quantity'=>$qty,'unit_price'=>$price,'total'=>$line]);$total+=$line;}$order->update(['total'=>$total,'due_at'=>now()->addHours((int)(LaundryService::whereIn('id',$d['laundry_service_id'])->max('turnaround_hours')?:24))]);});return back()->with('success','Laundry order created.');}public function status(Request $r,LaundryOrder $order,LaundryServiceManager $manager){abort_unless($order->property_id===auth()->user()->property_id,403);$d=$r->validate(['status'=>'required|in:received,washing,drying,ironing,ready,delivered,cancelled','assigned_to'=>'nullable|integer']);$manager->setStatus($order,$d['status'],auth()->id());if(array_key_exists('assigned_to',$d))$order->update(['assigned_to'=>$d['assigned_to']]);return back()->with('success','Laundry status updated.');}}
